}

export function summarizeJudge(rows) {
  const median = values => { const ordered = [...values].sort((a, b) => a - b); return ordered.length
    ? (ordered[Math.floor((ordered.length - 1) / 2)] + ordered[Math.ceil((ordered.length - 1) / 2)]) / 2 : null }
